import numpy as np

def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix):
    min_cost = float('inf')
    next_node = None

    for node in unvisited_nodes:
        cost = distance_matrix[current_node, node] + distance_matrix[node, destination_node]
        if cost < min_cost:
            min_cost = cost
            next_node = node

    return next_node
